<?php

namespace App\Models;

use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\Relations\BelongsTo;

/**
 * One photo of a crop listing (F1). The files are private (storage/app/private/crop-listing-photos)
 * and are only sent through CropListingPhotoController, which checks the listing's visibility
 * on every request. The paths are always generated by CropListingPhotoService, never taken from a form.
 */
class CropListingPhoto extends Model
{
    public const VARIANTS = ['thumb', 'display'];

    protected $fillable = [
        'position', 'display_path', 'thumbnail_path',
        'display_width', 'display_height', 'thumbnail_width', 'thumbnail_height',
    ];

    protected function casts(): array
    {
        return [
            'position' => 'integer',
            'display_width' => 'integer',
            'display_height' => 'integer',
            'thumbnail_width' => 'integer',
            'thumbnail_height' => 'integer',
        ];
    }

    /** The parent listing. A removed (soft-deleted) listing is not returned, so its photos stop being served. */
    public function listing(): BelongsTo
    {
        return $this->belongsTo(CropListing::class, 'crop_listing_id');
    }

    /** @param  'thumb'|'display'  $variant */
    public function url(string $variant = 'display'): string
    {
        return route('crop-listing-photos.show', ['photo' => $this->id, 'variant' => $variant]);
    }

    /** @param  'thumb'|'display'  $variant */
    public function pathFor(string $variant): string
    {
        return $variant === 'thumb' ? $this->thumbnail_path : $this->display_path;
    }
}
